class Solution {
    public List<String> findAndReplacePattern(String[] words,String pattern){
        List<String> answer=new ArrayList<>();
        for(String word:words)if(matches(word,pattern))answer.add(word);
        return answer;
    }
    private boolean matches(String word,String pattern){
        Map<Character,Character> forward=new HashMap<>(),backward=new HashMap<>();
        for(int i=0;i<word.length();i++){
            char a=word.charAt(i),b=pattern.charAt(i);
            if(forward.containsKey(a)&&forward.get(a)!=b||backward.containsKey(b)&&backward.get(b)!=a)return false;
            forward.put(a,b);
            backward.put(b,a);
        }
        return true;
    }
}

code.kotlin:
class Solution {
    fun findAndReplacePattern(words:Array<String>,pattern:String):List<String> = words.filter{
        matches(it,pattern)
    };
    private fun matches(word:String,pattern:String):Boolean{
        val forward=mutableMapOf<Char,Char>();
        val backward=mutableMapOf<Char,Char>();
        for(i in word.indices){
            val a=word[i];
            val b=pattern[i];
            if(forward.containsKey(a)&&forward[a]!=b||backward.containsKey(b)&&backward[b]!=a)return false;
            forward[a]=b;
            backward[b]=a
        };
        return true
    }
}

