class Solution {
    bool matches(string& word,string& pattern){
        unordered_map<char,char> forward,backward;
        for(int i=0;i<(int)word.size();++i){
            char a=word[i],b=pattern[i];
            if((forward.count(a)&&forward[a]!=b)||(backward.count(b)&&backward[b]!=a))return false;
            forward[a]=b;
            backward[b]=a;
        }
        return true;
    }
    public:vector<string> findAndReplacePattern(vector<string>& words,string pattern){
        vector<string> answer;
        for(string& word:words)if(matches(word,pattern))answer.push_back(word);
        return answer;
    }
};
